<?php require __DIR__.'/../includes/auth.php';$s=db()->prepare('SELECT status,COUNT(*) n FROM reservations WHERE user_id=? GROUP BY status');$s->execute([user()['id']]);$c=array_column($s->fetchAll(),'n','status');$pageTitle='My dashboard';require __DIR__.'/../includes/header.php';?><h1>Welcome, <?=e(user()['name'])?></h1><div class="stats"><div class="stat"><b><?=($c['PENDING']??0)+($c['CONFIRMED']??0)?></b>Upcoming stays</div><div class="stat"><b><?=$c['CHECKED_IN']??0?></b>Active stay</div><div class="stat"><b><?=$c['CHECKED_OUT']??0?></b>Completed stays</div><div class="stat"><b><?=$c['CANCELLED']??0?></b>Cancelled</div></div><p><a class="btn" href="<?=url('rooms/index.php')?>">Find a room</a></p><?php require __DIR__.'/../includes/footer.php'; ?>
